{
  "action_updates": [
    {
      "action_id": "A1",
      "preconditions": [],
      "postconditions": [
        {
          "requirement_id": "A1_post_1",
          "condition": "The hand washing operation has been performed.",
          "source": "explicit_instruction",
          "source_reference": "Wash your hands",
          "requires_expert_review": false,
          "evidence_specification": {
            "evidence_types": [
              "human_confirmation"
            ],
            "relevant_entities": [
              "hands"
            ],
            "observable_cues": [
              "confirmation that hands were washed with soap and water"
            ],
            "temporal_scope": "during_action",
            "verification_method": "human_confirmation",
            "observability": "not_observable",
            "current_support": "human_required",
            "limitations": [
              "appearance of wet or clean-looking hands in an after_step RGB frame does not prove the washing operation occurred"
            ]
          }
        }
      ],
      "error_criteria": [],
      "review_notes": [
        "Hand washing is a process-based requirement; RGB snapshots cannot verify the completion of the washing activity."
      ]
    },
    {
      "action_id": "A2",
      "preconditions": [
        {
          "requirement_id": "A2_pre_1",
          "condition": "The gloves to be used are clean.",
          "source": "explicit_instruction",
          "source_reference": "put on clean gloves",
          "requires_expert_review": true,
          "evidence_specification": {
            "evidence_types": [
              "human_confirmation"
            ],
            "relevant_entities": [
              "gloves"
            ],
            "observable_cues": [
              "provenance or visual confirmation that gloves are unused/clean"
            ],
            "temporal_scope": "before_action",
            "verification_method": "human_confirmation",
            "observability": "not_observable",
            "current_support": "human_required",
            "limitations": [
              "cleanliness is a material state that cannot be determined by RGB appearance alone"
            ]
          }
        }
      ],
      "postconditions": [
        {
          "requirement_id": "A2_post_1",
          "condition": "Clean gloves are worn on both hands.",
          "source": "explicit_instruction",
          "source_reference": "put on clean gloves",
          "requires_expert_review": false,
          "evidence_specification": {
            "evidence_types": [
              "rgb_frame",
              "object_mask"
            ],
            "relevant_entities": [
              "hands",
              "gloves"
            ],
            "observable_cues": [
              "gloves covering the user's hands"
            ],
            "temporal_scope": "after_action",
            "verification_method": "VLM",
            "observability": "visually_observable",
            "current_support": "supported",
            "limitations": [
              "occlusion may prevent seeing both hands"
            ]
          }
        }
      ],
      "error_criteria": [],
      "review_notes": []
    },
    {
      "action_id": "A3",
      "preconditions": [],
      "postconditions": [
        {
          "requirement_id": "A3_post_1",
          "condition": "The user has performed a visual inspection of the cut on the skin pad.",
          "source": "explicit_instruction",
          "source_reference": "Look at the cut on the skin pad.",
          "requires_expert_review": false,
          "evidence_specification": {
            "evidence_types": [
              "human_confirmation"
            ],
            "relevant_entities": [
              "cut",
              "skin pad"
            ],
            "observable_cues": [
              "confirmation that the user looked at the target"
            ],
            "temporal_scope": "during_action",
            "verification_method": "human_confirmation",
            "observability": "not_observable",
            "current_support": "human_required",
            "limitations": [
              "static RGB frames do not prove the cognitive act of looking"
            ]
          }
        },
        {
          "requirement_id": "A3_post_2",
          "condition": "The cut is confirmed to be not red, not swollen, and not leaking.",
          "source": "explicit_instruction",
          "source_reference": "Check that it is not red, swollen or leaking.",
          "requires_expert_review": true,
          "evidence_specification": {
            "evidence_types": [
              "rgb_frame"
            ],
            "relevant_entities": [
              "cut"
            ],
            "observable_cues": [
              "absence of red discoloration around the cut",
              "absence of visible fluid or discharge",
              "absence of raised/distended tissue around the cut"
            ],
            "temporal_scope": "after_action",
            "verification_method": "VLM",
            "observability": "partially_observable",
            "current_support": "partial",
            "limitations": [
              "swelling is difficult to assess in 2D RGB frames; clinical clearance requires expert review"
            ]
          }
        }
      ],
      "error_criteria": [
        {
          "criterion_id": "A3_E1",
          "error_type": "technique_error",
          "violation_condition": "The cut on the skin pad is red, swollen, or leaking.",
          "compliance_condition": "The cut on the skin pad is not red, swollen or leaking.",
          "applicability_condition": "The user is performing the inspection of the cut.",
          "related_requirement_ids": [
            "A3_post_2"
          ],
          "source": "explicit_instruction",
          "source_reference": "Check that it is not red, swollen or leaking.",
          "requires_expert_review": true,
          "evidence_specification": {
            "evidence_types": [
              "rgb_frame"
            ],
            "relevant_entities": [
              "cut"
            ],
            "observable_cues": [
              "redness around the cut",
              "fluid leaking from the cut",
              "bulging or distended skin around the cut"
            ],
            "temporal_scope": "after_action",
            "verification_method": "VLM",
            "observability": "partially_observable",
            "current_support": "partial",
            "limitations": [
              "lighting may cause false positives for redness; 2D view limits swelling detection"
            ]
          }
        }
      ],
      "review_notes": []
    }
  ],
  "procedure_error_criteria": [],
  "review_notes": []
}
